def _palette_jet(norm, label):
    colors = plt.cm.jet(np.linspace(0, 1, 256))[:, :3]
    cmap = ListedColormap(colors)
    return cmap, norm, label

PALETTE_DEFS = {
    'DBZH':  _palette_dbzh,
    'RATE':  _palette_rate,
    'VRADH': _palette_vradh,
    'ZDR':   lambda: _palette_jet(Normalize(vmin=-1,  vmax=3),   "Odbiciowość różnicowa ZDR [dB]"),
    'RHOHV': lambda: _palette_jet(Normalize(vmin=0.7, vmax=1.0), "Współczynnik korelacji RHOHV"),
    'KDP':   lambda: _palette_jet(Normalize(vmin=-1,  vmax=3),   "KDP [°/km]"),
    'PHIDP': lambda: _palette_jet(Normalize(vmin=0,   vmax=180), "PHIDP [°]"),
    'HGHT':  lambda: _palette_jet(Normalize(vmin=0,   vmax=15),  "Wysokość wierzchołków echa [km]"),
}

TICK_SPECS = {
    'DBZH':  [5, 10, 20, 30, 40, 50, 60, 65],
    'RATE':  [0.01, 0.05, 0.1, 0.5, 1, 5, 10, 50],
    'VRADH': [-30, -20, -10, 0, 10, 20, 30],
    'ZDR':   [-1, 0, 1, 2, 3],
    'RHOHV': [0.7, 0.8, 0.9, 0.95, 1.0],
    'KDP':   [-1, 0, 1, 2, 3],
    'PHIDP': [0, 30, 60, 90, 120, 150, 180],
    'HGHT':  [0, 3, 6, 9, 12, 15],
}

# ── Helpers ───────────────────────────────────────────────────────────────────

def to_hex(r, g, b):
    return f'#{int(r * 255 + .5):02x}{int(g * 255 + .5):02x}{int(b * 255 + .5):02x}'

def fmt_tick(v):
    if v == int(v):
        return str(int(v))
    return f'{v:.4f}'.rstrip('0').rstrip('.')

def compute_pct(v, vmin, vmax, scale):
    if scale == 'log':
        lmin, lmax = np.log10(vmin), np.log10(vmax)
        return float(np.clip((np.log10(max(v, vmin)) - lmin) / (lmax - lmin) * 100, 0, 100))
    return float(np.clip((v - vmin) / (vmax - vmin) * 100, 0, 100))

def export_quantity(quantity):
    cmap, norm, label = PALETTE_DEFS[quantity]()

    n = cmap.N
    discrete = n <= 64
    n_out = n if discrete else N_SAMPLES
    pts = np.linspace(0, 1, n_out)
    colors = [to_hex(*cmap(t)[:3]) for t in pts]

    if hasattr(norm, 'boundaries'):
        bounds = norm.boundaries
        vmin, vmax = float(bounds[0]), float(bounds[-1])
        scale = 'log'
    else:
        vmin, vmax = float(norm.vmin), float(norm.vmax)
        scale = 'linear'

    ticks = [
        {'value': float(v), 'label': fmt_tick(v), 'pct': compute_pct(v, vmin, vmax, scale)}
        for v in TICK_SPECS[quantity]
    ]

    return {
        'label': label,
        'type': scale,
        'discrete': discrete,
        'vmin': vmin,
        'vmax': vmax,
        'colors': colors,
        'ticks': ticks,
    }

# ── Main ──────────────────────────────────────────────────────────────────────

def main():
    palettes = {}
    for q in PALETTE_DEFS:
        try:
            p = export_quantity(q)
            palettes[q] = p
            print(f'  {q}: {len(p["colors"])} colors, {p["type"]}, {p["vmin"]:.3g}–{p["vmax"]:.3g}')
        except Exception as e:
            print(f'  WARNING {q}: {e}')

    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w', encoding='utf-8') as f:
        json.dump(palettes, f, ensure_ascii=False, indent=2)
    print(f'-> {OUT}')

if __name__ == '__main__':
    main()
